package app.studyforge.mobile;
import org.junit.Test;import org.json.*;import static org.junit.Assert.*;
public class ModelCatalogTest {
    @Test public void keepsOfficialSubscriptionOrderAndHidesUnlistedModels() throws Exception {JSONArray choices=ModelCatalog.parse(Json.object("models",Json.array(Json.object("slug","gpt-6-astra","display_name","Astra","visibility","list"),Json.object("slug","secret","visibility","hidden"),Json.object("slug","gpt-6.1-sol","display_name","Sol","visibility","list"))));assertEquals(2,choices.length());assertEquals("gpt-6-astra",choices.getJSONObject(0).getString("slug"));assertEquals("Sol",choices.getJSONObject(1).getString("name"));}
    @Test public void acceptsStandardAccountListWithoutInventingUnavailableModels() throws Exception {JSONArray choices=ModelCatalog.parse(Json.object("object","list","data",Json.array(Json.object("id","account-model"),Json.object("id","account-model"))));assertEquals(1,choices.length());assertEquals("account-model",choices.getJSONObject(0).getString("slug"));assertThrows(Exception.class,()->ModelCatalog.parse(Json.object("models",new JSONArray())));assertThrows(Exception.class,()->ModelCatalog.parse(Json.object("error","not a catalog")));}
    @Test public void largeCatalogMetadataIsNotExposedInPicker() throws Exception {JSONObject response=Json.object("models",Json.array(Json.object("slug","gpt-6.1-sol","visibility","list","instructions","x".repeat(2100000))));JSONArray out=ModelCatalog.parse(response);assertEquals(1,out.length());assertFalse(out.getJSONObject(0).has("instructions"));assertTrue(out.toString().length()<200);}
    @Test public void emptyDisplayNameStillShowsTheActualModelSlug() throws Exception {JSONArray choices=ModelCatalog.parse(Json.object("models",Json.array(Json.object("slug","gpt-6.1-sol","display_name","","visibility","list"))));assertEquals("gpt-6.1-sol",choices.getJSONObject(0).getString("name"));}
}
